/**
 * Triggers the display of a survey if it meets the display percentage criteria
 * @param survey - The survey configuration to potentially display
 */
export const triggerSurvey = (survey: TSurvey): void => {
  const surveyStore = SurveyStore.getInstance();
  const logger = Logger.getInstance();

  // A no-overlay survey leaves the host usable, so it can track again mid-survey. Without this
  // a different survey would replace the open one in place.
  const showing = surveyStore.getSurvey();
  if (showing) {
    logger.debug(
      `Survey display of "${survey.id}" skipped: survey "${showing.id}" is already showing.`,
    );
    return;
  }

  // Check if the survey should be displayed based on displayPercentage
  if (survey.displayPercentage) {
    const shouldDisplaySurvey = shouldDisplayBasedOnPercentage(
      survey.displayPercentage,
    );
    if (!shouldDisplaySurvey) {
      logger.debug(
        `Survey display of "${survey.id}" skipped based on displayPercentage.`,
      );
      return; // skip displaying the survey
    }
  }

  surveyStore.setSurvey(survey);
};

/**
 * Tracks an action name and triggers associated surveys
 * @param name - The name of the action to track
 * @param alias - Optional alias for the action name
 * @returns Result indicating success or network error
 */
export const trackAction = async (
  name: string,
  alias?: string,
): Promise<Result<void, NetworkError>> => {
  const logger = Logger.getInstance();
  const appConfig = await RNConfig.getInstance();

  const aliasName = alias ?? name;

  logger.debug(`Formbricks: Action "${aliasName}" tracked`);

  // get a list of surveys that are collecting insights
  const activeSurveys = appConfig.get().filteredSurveys;

  if (Boolean(activeSurveys) && activeSurveys.length > 0) {
    for (const survey of activeSurveys) {
      for (const trigger of survey.triggers) {
        if (trigger.actionClass.name === name) {
          triggerSurvey(survey);
        }
      }
    }
  } else {
    logger.debug("No active surveys to display");
  }

  return okVoid();
};

/**
 * Tracks an action by its code and triggers associated surveys (used for code actions only)
 * @param code - The action code to track
 * @returns Result indicating success, network error, or invalid code error
 */
export const track = async (
  code: string,
): Promise<
  | Result<void, NetworkError>
  | Result<void, InvalidCodeError>
  | Result<void, { code: "error"; message: string }>
> => {
  try {
    const appConfig = await RNConfig.getInstance();

    const netInfo = await fetch();

    if (!netInfo.isConnected) {
      return err({
        code: "network_error",
        status: 500,
        message:
          "No internet connection. Please check your connection and try again.",
        responseMessage:
          "No internet connection. Please check your connection and try again.",
        url: new URL(`${appConfig.get().appUrl}/js/surveys.umd.cjs`),
      });
    }

    const {
      workspace: {
        data: { actionClasses = [] },
      },
    } = appConfig.get();

    const codeActionClasses = actionClasses.filter(
      (action) => action.type === "code",
    );
    const actionClass = codeActionClasses.find((action) => action.key === code);

    if (!actionClass) {
      return err({
        code: "invalid_code",
        message: `Action with identifier '${code}' is unknown. Please add this action in Formbricks in order to use it via the SDK action tracking.`,
      });
    }

    return trackAction(actionClass.name, code);
  } catch (error) {
    const logger = Logger.getInstance();
    logger.error(`Error tracking action ${error as string}`);

    return err({
      code: "error",
      message: "Error tracking action",
    });
  }
};

import { Logger } from "@/lib/common/logger";
import { UpdateQueue } from "@/lib/user/update-queue";
import type { TSurvey } from "@/types/survey";

const logger = Logger.getInstance();

export type TInteractionSource = keyof NonNullable<
  TSurvey["interactionRefresh"]
>;

/**
 * Refresh server-computed segment membership after a survey interaction (display / response /
 * finish).
 *
 * A `surveyInteraction` segment filter can change who a contact is the moment they interact with
 * a survey (e.g. "have seen X", "have completed X"), so we pull fresh `segments` instead of
 * waiting for the user-state TTL. But that refresh is a heavy `/user` recompute, so it is:
 *   - Gated per survey and per event via `survey.interactionRefresh`: only interactions that can
 *     actually change some live survey's membership trigger a refetch. A survey referenced only
 *     by a "have seen" filter refreshes on display but not on response/finish, and a survey no
 *     interaction filter references never refreshes.
 *   - Routed through the UpdateQueue rather than a raw `sendUpdates`, so the display -> response
 *     -> finish burst coalesces into a single debounced call.
 *
 * No-op for anonymous users (no `userId`) and when the interaction can't change membership.
 */
export const refreshSegmentsAfterInteraction = (
  userId: string | null,
  survey: TSurvey,
  source: TInteractionSource,
): void => {
  if (!userId) return;

  const shouldRefresh = survey.interactionRefresh?.[source] ?? false;
  if (!shouldRefresh) return;

  logger.debug(`Refreshing segments after ${source} on survey ${survey.id}`);

  const updateQueue = UpdateQueue.getInstance();
  updateQueue.updateUserId(userId);
  // `processUpdates` rejects if the flush throws, and this is fire-and-forget — a bare
  // `void` would leave that as an unhandled rejection. The queue already logs the real
  // cause, so swallow it here rather than reporting it twice.
  void updateQueue.processUpdates().catch(() => undefined);
};

